-- Isolated local records only. Every mutation rolls back.
begin;
set local search_path=pg_catalog,public,extensions;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
alter table auth.users disable trigger on_auth_user_created;
insert into auth.users(id,email) values ('e1100000-0000-4000-8000-000000000001','schedule-owner@local.invalid'),('e1100000-0000-4000-8000-000000000002','schedule-employee@local.invalid');
alter table auth.users enable trigger on_auth_user_created;
insert into public.companies(id,name,operating_timezone) values ('e1200000-0000-4000-8000-000000000001','Synthetic schedule contractor','Pacific/Auckland'),('e1200000-0000-4000-8000-000000000002','Synthetic other contractor','UTC');
insert into public.profiles(id,company_id,role,full_name) values ('e1100000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','owner','Synthetic owner'),('e1100000-0000-4000-8000-000000000002','e1200000-0000-4000-8000-000000000001','employee','Synthetic employee');
insert into public.projects(id,company_id,job_number,name,status,sales_tax_exempt) values
 ('e1300000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','SYN-READY','Synthetic ready job','active',true),
 ('e1300000-0000-4000-8000-000000000002','e1200000-0000-4000-8000-000000000001','SYN-HELD','Synthetic held job','on_hold',true),
 ('e1300000-0000-4000-8000-000000000003','e1200000-0000-4000-8000-000000000002','SYN-FOREIGN','Synthetic foreign job','active',true);
insert into public.project_award_records(company_id,project_id,agreement_number,original_contract_value) values('e1200000-0000-4000-8000-000000000001','e1300000-0000-4000-8000-000000000001','SYN-AG',0);
insert into public.production_tasks(id,company_id,name,production_unit,active) values('e1500000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','Synthetic finish','SF',true);
insert into public.crew_members(id,company_id,name,role,active) values ('e1400000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','Synthetic active worker','finisher',true),('e1400000-0000-4000-8000-000000000002','e1200000-0000-4000-8000-000000000001','Synthetic inactive worker','finisher',false);
insert into public.work_packages(id,company_id,project_id,name) values('e1600000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','e1300000-0000-4000-8000-000000000001','Synthetic package');
insert into public.work_package_operations(id,company_id,work_package_id,production_task_id,field_label,planned_quantity,unit,requires_prior_operations) values ('e1700000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','e1600000-0000-4000-8000-000000000001','e1500000-0000-4000-8000-000000000001','Synthetic ready finish',100,'SF',false);
insert into public.pour_plans(id,company_id,project_id,name) values('e1800000-0000-4000-8000-000000000001','e1200000-0000-4000-8000-000000000001','e1300000-0000-4000-8000-000000000001','Synthetic linked pour');
insert into public.pour_plans(id,company_id,project_id,name) values('e1800000-0000-4000-8000-000000000002','e1200000-0000-4000-8000-000000000001','e1300000-0000-4000-8000-000000000001','Synthetic other pour');
insert into public.work_package_operations(id,company_id,work_package_id,production_task_id,field_label,planned_quantity,unit,requires_prior_operations,pour_plan_id) values('e1700000-0000-4000-8000-000000000002','e1200000-0000-4000-8000-000000000001','e1600000-0000-4000-8000-000000000001','e1500000-0000-4000-8000-000000000001','Synthetic pour operation',100,'SF',false,'e1800000-0000-4000-8000-000000000001');
create temp table schedule_input as select jsonb_build_object('project_id','e1300000-0000-4000-8000-000000000002','schedule_date','2026-10-16','item_type','work','title','Synthetic held planning','production_task_id','e1500000-0000-4000-8000-000000000001','crew_needed',1,'crew_member_ids',jsonb_build_array('e1400000-0000-4000-8000-000000000001','e1400000-0000-4000-8000-000000000001'),'start_time','23:00','end_time','02:00') payload;
create temp table schedule_results(key text primary key,value jsonb);grant all on schedule_results to authenticated;grant select on schedule_input to authenticated;
create function pg_temp.schedule_request(n integer,c text,p jsonb) returns jsonb language sql as $$ select public.carez_schedule_command_v1(('e1900000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,c,p) $$;
select set_config('request.jwt.claim.sub','e1100000-0000-4000-8000-000000000001',true);set local role authenticated;
select extensions.lives_ok($$insert into schedule_results values('held',pg_temp.schedule_request(1,'create',(select payload from schedule_input)))$$,'held planning and crew assignments commit together');
select extensions.is((select count(*)::integer from public.work_schedule_items),1,'one planned item');
select extensions.is((select count(*)::integer from public.work_schedule_assignments),1,'duplicate crew is one assignment');
select extensions.lives_ok($$select pg_temp.schedule_request(1,'create',(select payload from schedule_input))$$,'confirmed create retry is safe');
select extensions.is((select count(*)::integer from public.work_schedule_items),1,'retry does not duplicate item');
select extensions.throws_like($$select pg_temp.schedule_request(1,'create',(select payload||'{"title":"Changed"}' from schedule_input))$$,'%different values%','changed request conflicts');
select extensions.throws_like($$select pg_temp.schedule_request(2,'status',(select jsonb_build_object('id',value->>'id','expected_revision',0,'status','confirmed') from schedule_results where key='held'))$$,'%Job setup hold:%','held confirmation denied');
select extensions.throws_like($$select pg_temp.schedule_request(2,'create',(select payload||'{"status":"confirmed"}' from schedule_input))$$,'%must be planned%','forged create confirmation denied');
select extensions.throws_like($$select pg_temp.schedule_request(2,'create',(select payload||'{"crew_member_ids":["e1400000-0000-4000-8000-000000000002"]}' from schedule_input))$$,'%crew member is unavailable%','inactive assignment rejected atomically');
select extensions.is((select count(*)::integer from public.work_schedule_items),1,'failed crew leaves no orphan');
select extensions.throws_like($$select pg_temp.schedule_request(2,'create',(select payload||'{"project_id":"e1300000-0000-4000-8000-000000000003"}' from schedule_input))$$,'%job unavailable%','foreign job denied');
select extensions.throws_like($$select pg_temp.schedule_request(2,'create',(select payload||'{"work_package_operation_id":"e1700000-0000-4000-8000-000000000001"}' from schedule_input))$$,'%does not belong to this job%','same-company wrong-job operation denied');
select extensions.throws_like($$select pg_temp.schedule_request(2,'create',(select payload||'{"schedule_date":"infinity"}' from schedule_input))$$,'%finite schedule date%','nonfinite date rejected');
select extensions.lives_ok($$insert into schedule_results values('moved',pg_temp.schedule_request(2,'reschedule',(select jsonb_build_object('id',value->>'id','expected_revision',0,'schedule_date','2026-10-17') from schedule_results where key='held')))$$,'held plan can be moved');
select extensions.is((select command_revision from public.work_schedule_items),1::bigint,'move advances schedule revision');
select extensions.lives_ok($$select pg_temp.schedule_request(2,'reschedule',(select jsonb_build_object('id',value->>'id','expected_revision',0,'schedule_date','2026-10-17') from schedule_results where key='held'))$$,'move replay uses confirmed outcome before stale check');
select extensions.throws_like($$select pg_temp.schedule_request(3,'reschedule',(select jsonb_build_object('id',value->>'id','expected_revision',0,'schedule_date','2026-10-18') from schedule_results where key='held'))$$,'%Schedule changed%','stale move rejected');
select extensions.lives_ok($$insert into schedule_results values('ready',pg_temp.schedule_request(3,'create',(select payload||'{"project_id":"e1300000-0000-4000-8000-000000000001","work_package_operation_id":"e1700000-0000-4000-8000-000000000001","title":""}' from schedule_input)))$$,'operation supplies title and task');
select extensions.lives_ok($$select pg_temp.schedule_request(4,'status',(select jsonb_build_object('id',value->>'id','expected_revision',0,'status','confirmed') from schedule_results where key='ready'))$$,'explicit authoritative ready work can be confirmed');
select extensions.is((select status from public.work_package_operations limit 1),'planned','schedule confirmation does not start physical operation');
select extensions.lives_ok($$insert into schedule_results values('inspection',pg_temp.schedule_request(5,'create',(select payload||'{"project_id":"e1300000-0000-4000-8000-000000000001","work_package_operation_id":"e1700000-0000-4000-8000-000000000001","item_type":"inspection","title":"Synthetic inspection","pour_plan_id":"e1800000-0000-4000-8000-000000000001"}' from schedule_input)))$$,'inspection source and derived schedule survive schedule ACL revocation');
select extensions.is((select count(*)::integer from public.project_inspections),1,'one authoritative inspection');
select extensions.is((select pour_plan_id from public.work_schedule_items where inspection_id is not null),'e1800000-0000-4000-8000-000000000001'::uuid,'inspection planning preserves the selected pour link');
select extensions.lives_ok($$update public.project_inspections set status='failed',result_notes='Synthetic test result'$$,'inspection result can still be recorded');
select extensions.is((select status from public.work_schedule_items where id=(select (value->>'id')::uuid from schedule_results where key='ready')),'planned','failed inspection atomically demotes affected confirmation');
select extensions.throws_like($$select pg_temp.schedule_request(8,'delete',(select jsonb_build_object('id',s.id,'expected_revision',s.command_revision) from public.work_schedule_items s where s.inspection_id is not null))$$,'%Inspection result history%','schedule removal cannot erase a failed inspection hold');
select extensions.throws_like($$select pg_temp.schedule_request(6,'status',(select jsonb_build_object('id',value->>'id','expected_revision',2,'status','confirmed') from schedule_results where key='ready'))$$,'%Work is on hold:%','failed inspection blocks reconfirmation');
select extensions.throws_like($$update public.work_schedule_items set status='confirmed'$$,'%permission denied%','raw confirmation denied');
select extensions.throws_like($$delete from public.work_schedule_assignments$$,'%permission denied%','raw assignment mutation denied');
select extensions.lives_ok($$select pg_temp.schedule_request(6,'delete',(select jsonb_build_object('id',value->>'id','expected_revision',1) from schedule_results where key='held'))$$,'delete command removes item and assignments');
select extensions.lives_ok($$select pg_temp.schedule_request(6,'delete',(select jsonb_build_object('id',value->>'id','expected_revision',1) from schedule_results where key='held'))$$,'deletion replay survives absent target');
select extensions.is(public.carez_company_calendar_date('e1200000-0000-4000-8000-000000000001','2026-10-16T12:30:00Z'),'2026-10-17'::date,'company calendar uses its configured day');
select extensions.throws_like($$select pg_temp.schedule_request(9,'create',(select payload||'{"project_id":"e1300000-0000-4000-8000-000000000001","work_package_operation_id":"e1700000-0000-4000-8000-000000000002","pour_plan_id":"e1800000-0000-4000-8000-000000000002"}' from schedule_input))$$,'%conflicts with the operation source pour%','same-job alternate pour cannot misrepresent operation readiness');
select extensions.lives_ok($$insert into schedule_results values('source-pour',pg_temp.schedule_request(9,'create',(select payload||'{"project_id":"e1300000-0000-4000-8000-000000000001","work_package_operation_id":"e1700000-0000-4000-8000-000000000002"}' from schedule_input)))$$,'operation supplies its authoritative pour reference when omitted');
select extensions.is((select pour_plan_id from public.work_schedule_items where id=(select (value->>'id')::uuid from schedule_results where key='source-pour')),'e1800000-0000-4000-8000-000000000001'::uuid,'saved reference uses the operation source');
reset role;
create temp table schedule_view_definition as select pg_get_viewdef('public.project_job_readiness_summary'::regclass,true) definition;
do $$declare definition text;begin select rtrim(btrim(d.definition),';') into definition from schedule_view_definition d;execute 'create or replace view public.project_job_readiness_summary with(security_invoker=true) as select * from ('||definition||') b where b.project_id<>''e1300000-0000-4000-8000-000000000001''::uuid';end $$;
set local role authenticated;
select extensions.throws_like($$select pg_temp.schedule_request(7,'status',(select jsonb_build_object('id',value->>'id','expected_revision',2,'status','confirmed') from schedule_results where key='ready'))$$,'%Job readiness unavailable%','successfully missing job readiness fails closed');
reset role;
create function pg_temp.schedule_read_failure() returns boolean language plpgsql as $$begin raise exception 'Synthetic readiness read failure';end $$;
do $$declare definition text;begin select rtrim(btrim(d.definition),';') into definition from schedule_view_definition d;execute 'create or replace view public.project_job_readiness_summary with(security_invoker=true) as select * from ('||definition||') b where pg_temp.schedule_read_failure()';end $$;
set local role authenticated;
select extensions.throws_like($$select pg_temp.schedule_request(7,'status',(select jsonb_build_object('id',value->>'id','expected_revision',2,'status','confirmed') from schedule_results where key='ready'))$$,'%Synthetic readiness read failure%','failed readiness query cannot authorize confirmation');
select extensions.is((select status from public.work_schedule_items where id=(select (value->>'id')::uuid from schedule_results where key='ready')),'planned','failed read preserves planned state');
reset role;
do $$declare definition text;begin select d.definition into definition from schedule_view_definition d;execute 'create or replace view public.project_job_readiness_summary with(security_invoker=true) as '||definition;end $$;
set local role authenticated;
select set_config('request.jwt.claim.sub','e1100000-0000-4000-8000-000000000002',true);
select extensions.throws_like($$select pg_temp.schedule_request(7,'create',(select payload from schedule_input))$$,'%Owner or office authority%','employee cannot change office schedule');
select * from extensions.finish();rollback;
